import json

G = {}
G['demo_input'] = [[6, 5, 5], [5, 1, 7], [4, 5, 2]]
G['demo_output'] = [[6, 6, 5, 5, 5], [6, 6, 5, 5, 5], [5, 5, 1, 7, 7], [4, 4, 5, 2, 2], [4, 4, 5, 2, 2]]
G['test_input'] = [[1, 2, 5], [7, 3, 6], [7, 6, 5]]

def expand_row(row):
    """Expand row based on right neighbor relationship"""
    result = []
    for i in range(len(row)):
        val = row[i]
        if i == len(row) - 1:
            # Last element: always duplicate
            result.extend([val] * 2)
        elif row[i] != row[i+1]:
            # Different from right: duplicate
            result.extend([val] * 2)
        else:
            # Same as right: include once
            result.append(val)
    return result

def transform(input_grid):
    h_in, w_in = len(input_grid), len(input_grid[0])
    result = []
    for r in range(h_in):
        expanded = expand_row(list(input_grid[r]))
        result.append(expanded)
        result.append(expanded)  # Duplicate each row vertically
    return result

pred = transform(G['demo_input'])
print("Prediction:")
for row in pred: print(row)

print("\nActual:")
for row in G['demo_output']: print(row)

matches = sum(1 for a,b in zip(G['demo_output'], pred) if a==b)
