import json

G = {}
G['demo_input'] = [[6, 5, 5], [5, 1, 7], [4, 5, 2]]
G['demo_output'] = [[6, 6, 5, 5, 5], [6, 6, 5, 5, 5], [5, 5, 1, 7, 7], [4, 4, 5, 2, 2], [4, 4, 5, 2, 2]]
G['test_input'] = [[1, 2, 5], [7, 3, 6], [7, 6, 5]]

def expand_row(row):
    """Expand row: first position → 2 cells, middle → 1 cell, last → 2 cells"""
    n = len(row)
    if n == 0:
        return []
    elif n == 1:
        return [row[0], row[0]]
    else:
        result = [row[0], row[0]]
        for i in range(1, n-1):
            result.append(row[i])
        result.extend([row[n-1], row[n-1]])
    return result

def has_duplicates(row):
    """Check if row has any duplicate values"""
    return len(set(row)) < len(row)

def transform_v4(input_grid):
    """Rows WITH duplicates get expanded ONCE, rows WITHOUT duplicates get EXPANDED TWICE"""
    result = []
    for r in range(len(input_grid)):
        expanded = expand_row(list(input_grid[r]))
        result.append(expanded)
        if not has_duplicates(list(input_grid[r])):
            # No duplicates: duplicate this row
            result.append(expanded)
    return result

pred = transform_v4(G['demo_input'])
print("Prediction:")
for i, row in enumerate(pred): print(f"Row {i}: {row}")

print("\nActual:")
for i, row in enumerate(G['demo_output']): print(f"Row {i}: {row}")

matches = sum(1 for a,b in zip(G['demo_output'], pred) if a==b)
print(f"\nMatches: {matches}/{len(G['demo_output'])}")

if matches == len(G['demo_output']):
    print("\nPattern confirmed!")
    test_pred = transform_v4(G['test_input'])
    print("\nTest input prediction:")
    for row in test_pred: print(row)
    print(json.dumps(test_pred))
else:
    print("Still doesn't match")
